CREATE OR REPLACE FUNCTION public.admin_update_user_full(p_target_user_id UUID, p_first_name TEXT, p_last_name TEXT, p_region TEXT, p_state TEXT, p_role TEXT, p_zone_id UUID, p_organization_id UUID, p_zone_ids UUID[]) RETURNS JSONB SECURITY DEFINER SET search_path = public AS $$$ DECLARE v_caller_role TEXT; v_caller_org UUID; v_target_org UUID; BEGIN SELECT role, organization_id INTO v_caller_role, v_caller_org FROM public.user_roles_plain WHERE user_id = auth.uid(); IF v_caller_role IS NULL THEN RETURN '{"error": "Unauthorized. No se pudo verificar la identidad."}'::jsonb; END IF; IF v_caller_role NOT IN ('master', 'admin') THEN RETURN '{"error": "Unauthorized. Acceso denegado, se requiere nivel Master o Admin."}'::jsonb; END IF; IF v_caller_role = 'admin' THEN SELECT organization_id INTO v_target_org FROM public.user_roles_plain WHERE user_id = p_target_user_id; IF v_target_org != v_caller_org THEN RETURN '{"error": "Unauthorized. Solo puedes editar colaboradores de tu misma organización."}'::jsonb; END IF; IF p_role = 'master' THEN RETURN '{"error": "Unauthorized. Los administradores no pueden asignar el nivel Master."}'::jsonb; END IF; p_organization_id := v_caller_org; END IF; UPDATE public.profiles SET first_name = p_first_name, last_name = p_last_name, region = p_region, state = p_state WHERE user_id = p_target_user_id; UPDATE public.user_roles SET role = p_role, region = p_region, state = p_state, zone_id = p_zone_id, organization_id = COALESCE(p_organization_id, organization_id) WHERE user_id = p_target_user_id; UPDATE public.user_roles_plain SET role = p_role, region = p_region, state = p_state, zone_id = p_zone_id, organization_id = COALESCE(p_organization_id, organization_id) WHERE user_id = p_target_user_id; DELETE FROM public.user_zones WHERE user_id = p_target_user_id; IF array_length(p_zone_ids, 1) > 0 THEN INSERT INTO public.user_zones (user_id, zone_id) SELECT p_target_user_id, unnest(p_zone_ids); END IF; RETURN '{"success": true}'::jsonb; EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $$$ LANGUAGE plpgsql; NOTIFY pgrst, 'reload schema';
